namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void CanCreateContext_WithInMemoryDatabase()
        {
            using var context = TestDbContextFactory.Create();

            Assert.NotNull(context);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            using var context = TestDbContextFactory.Create();

            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };
            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.First(s => s.LastName == "Test");
            Assert.Equal("User", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            using var context = TestDbContextFactory.Create();

            var dept = new Department
            {
                Name = "Science",
                Budget = 50000m,
                StartDate = DateTime.Now
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 5001,
                Title = "Biology",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.Include(c => c.Department).First(c => c.CourseID == 5001);
            Assert.Equal("Biology", retrieved.Title);
            Assert.Equal("Science", retrieved.Department.Name);
        }

        [Fact]
        public void CanAddEnrollment_WithStudentAndCourse()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var enrollment = new Enrollment
            {
                CourseID = 1001,
                StudentID = 2,
                Grade = Grade.B
            };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            var retrieved = context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.StudentID == 2 && e.CourseID == 1001);
            Assert.Equal(Grade.B, retrieved.Grade);
            Assert.Equal("Brown", retrieved.Student.LastName);
            Assert.Equal("Calculus", retrieved.Course.Title);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var assignment = context.CourseAssignments
                .First(ca => ca.InstructorID == 1 && ca.CourseID == 1001);

            Assert.NotNull(assignment);
        }

        [Fact]
        public void Instructor_HasOfficeAssignment()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var instructor = context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.ID == 1);

            Assert.NotNull(instructor.OfficeAssignment);
            Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
        }

        [Fact]
        public void Instructor_WithoutOfficeAssignment_IsNull()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var instructor = context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.ID == 2);

            Assert.Null(instructor.OfficeAssignment);
        }

        [Fact]
        public void Person_FullName_ReturnsCorrectFormat()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane"
            };

            Assert.Equal("Doe, Jane", student.FullName);
        }

        [Fact]
        public void CanDeleteStudent_CascadesEnrollments()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var student = context.Students
                .Include(s => s.Enrollments)
                .First(s => s.ID == 1);

            var enrollmentCount = student.Enrollments.Count;
            Assert.True(enrollmentCount > 0);

            context.Students.Remove(student);
            context.SaveChanges();

            Assert.Null(context.Students.Find(1));
        }
    }
}

