using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllData()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"DbInit_{Guid.NewGuid()}")
                .Options;

            using var context = new SchoolContext(options);
            context.Database.EnsureCreated();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.True(context.CourseAssignments.Count() >= 8);
            Assert.True(context.Enrollments.Count() >= 11);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"DbInit_{Guid.NewGuid()}")
                .Options;

            using var context = new SchoolContext(options);
            context.Database.EnsureCreated();

            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            // Run again
            DbInitializer.Initialize(context);

            Assert.Equal(studentCount, context.Students.Count());
        }

        [Fact]
        public void Initialize_SetsCorrectDepartmentAdministrators()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"DbInit_{Guid.NewGuid()}")
                .Options;

            using var context = new SchoolContext(options);
            context.Database.EnsureCreated();

            DbInitializer.Initialize(context);

            var englishDept = context.Departments.First(d => d.Name == "English");
            var admin = context.Instructors.Find(englishDept.InstructorID);
            Assert.Equal("Abercrombie", admin.LastName);
        }

        [Fact]
        public void Initialize_CreatesCourseAssignments()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"DbInit_{Guid.NewGuid()}")
                .Options;

            using var context = new SchoolContext(options);
            context.Database.EnsureCreated();

            DbInitializer.Initialize(context);

            var chemCourse = context.Courses.First(c => c.Title == "Chemistry");
            var assignments = context.CourseAssignments.Where(ca => ca.CourseID == chemCourse.CourseID).ToList();
            Assert.Equal(2, assignments.Count);
        }

        [Fact]
        public void Initialize_CreatesEnrollmentsWithGrades()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"DbInit_{Guid.NewGuid()}")
                .Options;

            using var context = new SchoolContext(options);
            context.Database.EnsureCreated();

            DbInitializer.Initialize(context);

            var alexander = context.Students.First(s => s.LastName == "Alexander");
            var enrollments = context.Enrollments.Where(e => e.StudentID == alexander.ID).ToList();
            Assert.Equal(3, enrollments.Count);
            Assert.Contains(enrollments, e => e.Grade == Grade.A);
        }
    }
}

